ee:message.ee:set-payload:
%dw 2.0
output text/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tem http://tempuri.org/
---
soapenv#Envelope @("xmlns:tem":"http://tempuri.org/"): {
    soapenv#Header: "",
        soapenv#Body: {
            tem#ConsultarServicioClienteByNit:{
                tem#Nit: attributes.queryParams.nit,
                tem#nombre_producto: attributes.queryParams.product_name,
                tem#id_servicio: attributes.queryParams.id_servicio,
                tem#cliente:""
            }
        }
}

%dw 2.0
output application/json
---
if (!isEmpty(payload.ConsultServiceByNitOutput))
payload
else
{
  "ConsultServiceByNitOutput": {
    "WSResponseHeader2": {
      "System": {
        "name":  vars.headers.name ,
        "correlationID":  vars.headers."x-correlation-id" ,
        "processingServer": ""
      },
      "Service": {
        "status": p('gestor.ifNull.fail'),
        "responseDate": now() ,
        "statusDetail": {
          "errorCode": p('gestor.ifNull.fail'),
          "errorMessage": p('gestor.ifNull.errorMessage')
        }
      }
    }
  }
}
